"""Independent probes in frozen review only; real loopback sinks."""
import json
import unittest
from test_compliance import ComplianceTests

class EmptyReview(unittest.TestCase):
    router = ComplianceTests.router
    request = ComplianceTests.request
    private_only = ComplianceTests.private_only

    def positions(self, key):
        yield {'messages': [], key: None}
        yield {'messages': [{'role': 'user', 'content': 'clean', key: None}]}
        yield {'messages': [], 'provider': {key: None}}
        yield {'messages': [], 'tools': [{'type': 'function', 'function': {'name': 'f'}, key: None}]}
        yield {'messages': [], 'tools': [{'type': 'function', 'function': {'name': 'f', key: None}}]}
        yield {'messages': [], 'functions': [{'name': 'f', key: None}]}
        yield {'messages': [{'role': 'assistant', 'function_call': {'name': 'f', 'arguments': '{}', key: None}}]}
        yield {'messages': [{'role': 'assistant', 'tool_calls': [{'id': 'c', 'type': 'function', 'function': {'name': 'f', 'arguments': '{}'}, key: None}]}]}
        yield {'messages': [{'role': 'assistant', 'tool_calls': [{'id': 'c', 'type': 'function', 'function': {'name': 'f', 'arguments': '{}', key: None}}]}]}
        yield {'messages': [{'role': 'user', 'content': [{'type': 'text', 'text': 'clean', key: None}]}]}

    def test_protocol_unknown_keys(self):
        keys = ['', '|', '||', 'name|arguments', '|name', 'name|', 'na', 'Name', 'name ', ' name', 'ｎａｍｅ', 'name\u200b', 'x' * 120, 'x' * 121]
        with self.router() as (p, private, public):
            for key in keys:
                for pos, fields in enumerate(self.positions(key)):
                    with self.subTest(key=key, position=pos):
                        self.private_only(p, private, public, {'model': 'alias', **fields})
        self.assertEqual(self.last_stderr.count(b'compliance_reason=unknown endpoint=private'), len(keys) * 10)

    def data_positions(self, value):
        data = {'': value}
        yield {'messages': [{'role': 'user', 'content': json.dumps(data)}]}
        yield {'messages': [{'role': 'user', 'content': json.dumps(json.dumps(data))}]}
        yield {'messages': [{'role': 'assistant', 'tool_calls': [{'type': 'function', 'function': {'name': 'f', 'arguments': json.dumps(data)}}]}]}
        yield {'messages': [{'role': 'assistant', 'function_call': {'name': 'f', 'arguments': json.dumps(data)}}]}
        yield {'messages': [], 'metadata': data}
        yield {'messages': [], 'tools': [{'type': 'function', 'function': {'name': 'f', 'parameters': {'type': 'object', 'properties': {'': {'description': value}}}}}]}
        yield {'messages': [], 'response_format': {'type': 'json_schema', 'json_schema': {'name': 'f', 'schema': {'properties': {'': {'description': value}}}}}}

    def test_empty_data_keys_clean_public(self):
        with self.router() as (p, private, public):
            for fields in self.data_positions('clean'):
                body = {'model': 'alias', **fields}
                before = len(public.seen)
                self.assertEqual(self.request(p, body=body)[0], 200)
                self.assertEqual(len(public.seen), before + 1)
                self.assertEqual(public.seen[-1], {**body, 'model': 'public-model', 'provider': {'allow_fallbacks': False}})
                self.assertEqual(private.connections, 0)
                self.assertEqual(private.bytes_seen, 0)
        self.assertEqual(self.last_stderr.count(b'compliance_reason=clean endpoint=public'), 7)

    def test_empty_data_keys_sensitive_private(self):
        with self.router() as (p, private, public):
            for fields in self.data_positions('synthetic@example.test'):
                self.private_only(p, private, public, {'model': 'alias', **fields})
        self.assertEqual(self.last_stderr.count(b'compliance_reason=pattern endpoint=private'), 7)

if __name__ == '__main__':
    unittest.main()
